function binarySearch(data, target, mids) {
  let low = 1;
  let high = data.length;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    mids.push(mid);
    if (data[mid - 1] === target) return mid;
    else if (data[mid - 1] < target) low = mid + 1;
    else high = mid - 1;
  }
  return -1;
}
const mids = [];
binarySearch([4, 9, 13, 18, 25, 31, 37, 42, 50], 42, mids);
return mids.join('，');
